import fs from 'node:fs';
import assert from 'node:assert/strict';
import {hash,json} from './seal-simple-website-successor.mjs';
const source='F:/VisibleMedicine/staging/20261024-practice-actions-website/SOURCE_BOUND.json';
assert.equal(json(source).atlasHead,'7659453d7d99da78742b06ee6e6665a467e5d972');
const file='CURRENT_CHECKPOINT.json',p=json(file),before=structuredClone(p);
assert.equal(p.activeWork.current.ownerPreviewPolicy.restartPermitted,false);assert.equal(p.activeWork.current.activeExecutionSessions.length,0);
const root='F:/VisibleMedicine/recovery/checkpoints/20261024-practice-actions-website-index-history';
assert(!fs.existsSync(root));fs.mkdirSync(root);
const old=p.activeWork.current.pendingPracticeActions;
assert.equal(old.fullWebsiteIntegrationPending,true);assert.equal(hash(old.sourceReceipt),old.sourceReceiptSha256);
const history={at:new Date().toISOString(),previousArchive:p.historyArchive,originalFields:{'activeWork.current.pendingPracticeActions':old,'coordination.releaseChat.observerTriage':p.coordination.releaseChat.observerTriage}};
const write=(file,value)=>fs.writeFileSync(file,JSON.stringify(value,null,2)+'\n',{flag:'wx'});
write(root+'/history.json',history);write(root+'/field-index.json',{at:history.at,fields:Object.keys(history.originalFields),previousArchive:history.previousArchive,readPolicy:'Historical values preserve their original paths and state; missing details do not imply approval, completion or permission.'});
p.historyArchive={path:root+'/history.json',sha256:hash(root+'/history.json'),fieldIndex:root+'/field-index.json',allHistoryRetained:true,priorArchiveIn:'previousArchive',readPolicy:before.historyArchive.readPolicy};
p.activeWork.current.pendingPracticeActions={checkpoint:old.checkpoint,checkpointSha256:old.checkpointSha256,sourceReceipt:old.sourceReceipt,sourceReceiptSha256:old.sourceReceiptSha256,atlasHead:old.atlasHead,fullWebsiteIntegrationPending:false,composedInto:source,composedIntoSha256:hash(source),detailsArchivedAtOriginalPath:true,previewChanged:false,installed:false};
const report='F:/VisibleMedicine/staging/20261024-observer-triage/REPORT.json';assert.equal(json(report).source.atlasHead,old.atlasHead);
p.coordination.releaseChat.observerTriage={...p.coordination.releaseChat.observerTriage,state:'completed-unlocalized',cursor:'09786c67-a526-4f3e-9592-4f73d6c47d39:58',report,reportSha256:hash(report),sourcePatched:false,exportPatched:false,browserReplayRun:false,fullStackStillRequired:true};
for(const key of ['goal','safety'])assert.deepEqual(p[key],before[key]);
for(const key of ['ownerPreviewPolicy','currentInstalled','activeExecutionSessions','latestWebsiteCandidate'])assert.deepEqual(p.activeWork.current[key],before.activeWork.current[key]);
const inverse=structuredClone(p);inverse.historyArchive=before.historyArchive;inverse.activeWork.current.pendingPracticeActions=old;inverse.coordination.releaseChat.observerTriage=before.coordination.releaseChat.observerTriage;assert.deepEqual(inverse,before);
const text=JSON.stringify(p,null,2)+'\n';assert(Buffer.byteLength(text)<65536);fs.writeFileSync(file,text);
console.log(JSON.stringify({history:root+'/history.json',sha256:hash(root+'/history.json'),indexBytes:Buffer.byteLength(text),fullGoalPreserved:true,previewChanged:false}));
